$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest

$Root = Split-Path -Parent $MyInvocation.MyCommand.Path
Set-Location $Root

$Target = Join-Path $Root 'e2e\certification-all-ancestries.spec.ts'
$Encoded = @'

'@

$Bytes = [System.Convert]::FromBase64String($Encoded.Trim())
[System.IO.File]::WriteAllBytes($Target, $Bytes)

Write-Host 'Ancestry E2E dosyasi temiz ve gecerli kaynakla yeniden yazildi.'
Write-Host ''
Write-Host 'ANCESTRY FOCUSED E2E BASLIYOR'

& npm.cmd exec playwright test -- `
  e2e/certification-all-ancestries.spec.ts `
  --project=desktop-chromium `
  --workers=1 `
  --max-failures=5

$code = $LASTEXITCODE
if ($code -ne 0) {
  Write-Host "N-MEGA12 HOTFIX10 RED (exit=$code)"
  exit $code
}

Write-Host 'N-MEGA12 HOTFIX10 ANCESTRY GREEN'
